List = list

def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """Check if any two numbers in the list are closer than the given threshold."""
    if len(numbers) < 2:
        return False
    sorted_nums = sorted(numbers)
    for i in range(len(sorted_nums) - 1):
        if abs(sorted_nums[i + 1] - sorted_nums[i]) < threshold:
            return True
    return False

def truncate_number(number: float) -> float:
    """
    Return the decimal part of a positive floating point number.
    """
    return number - int(number)

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def find_topmost_carpet(n, carpets, point) -> int:
    x, y = point
    for i in range(n - 1, -1, -1):
        a, b, g, k = carpets[i]
        if a <= x <= a + g and b <= y <= b + k:
            return i + 1
    return -1

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue
        # Determine sign
        if not terms:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '+' if coeff > 0 else '-'
        abs_coeff = abs(coeff)
        # Coefficient string
        coeff_str = ''
        if abs_coeff != 1 or degree == 0:
            coeff_str = str(abs_coeff)
        # Variable part
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''
        terms.append(f'{sign}{coeff_str}{var_str}')
    return ''.join(terms) if terms else '0'

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # The encoded and original strings must be of the same length
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    reverse_mapping = {}

    for e, o in zip(encoded, original):
        # Check for consistency of the mapping
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

        # Ensure the mapping is bijective (each original letter comes from only one encoded letter)
        if o in reverse_mapping:
            if reverse_mapping[o] != e:
                return "Failed"
        else:
            reverse_mapping[o] = e

    # The mapping must cover all 26 letters of the alphabet
    if len(mapping) != 26 or len(reverse_mapping) != 26:
        return "Failed"

    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])

    return "".join(decoded_chars)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to 10 steps to find the minimum number of transformations.
    """
    max_steps = 10
    # Each element in queue: (current_string, steps_taken)
    queue = [(A, 0)]
    visited = {A}
    while queue:
        current, steps = queue.pop(0)
        if steps > max_steps:
            continue
        if current == B:
            return steps
        if steps == max_steps:
            continue
        # Generate all possible next strings
        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = idx + 1  # allow overlapping matches
    return "NO ANSWER!"

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers reachable from the original integer `n` by applying
    the given digit transformation rules. Each rule is a tuple (x, y) meaning
    digit `x` can be transformed into digit `y`. The function performs a breadth-first
    search over all possible single-digit transformations and returns the count
    of distinct numbers (including the original number).
    """
    from collections import deque

    # Map each digit to the list of digits it can transform into
    rule_map = {}
    for x, y in rules:
        rule_map.setdefault(str(x), []).append(str(y))

    start = str(n)
    visited = {int(start)}
    queue = deque([start])

    while queue:
        current = queue.popleft()
        for i, d in enumerate(current):
            if d in rule_map:
                for new_d in rule_map[d]:
                    new_num_str = current[:i] + new_d + current[i+1:]
                    new_num = int(new_num_str)
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num_str)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    for speaker, stmts in statements.items():
        for stmt in stmts:
            # Skip statements that mention a day of the week
            if any(day in stmt for day in days_of_week):
                continue

            # Normalize statement
            st = stmt.strip()

            # Determine the truth value of the statement
            truth = None
            if st == "I am guilty.":
                truth = (scenario == speaker)
            elif st == "I am not guilty.":
                truth = (scenario != speaker)
            else:
                parts = st.split(" is ")
                if len(parts) == 2:
                    name, rest = parts
                    if rest == "guilty.":
                        truth = (scenario == name)
                    elif rest == "not guilty.":
                        truth = (scenario != name)

            # If the statement is not recognized, ignore it
            if truth is None:
                continue

            # Check consistency with liar status
            is_liar = speaker in liar_count
            if is_liar and truth:
                return False
            if not is_liar and not truth:
                return False

    return True

