def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    if m > sum(a):
        return 0
    dp_prev = [0] * (m + 1)
    dp_prev[0] = 1
    for i in range(n):
        limit = a[i]
        dp_cur = [0] * (m + 1)
        prefix = [0] * (m + 1)
        prefix[0] = dp_prev[0]
        for j in range(1, m + 1):
            prefix[j] = (prefix[j - 1] + dp_prev[j]) % MOD
        for j in range(m + 1):
            low = j - limit
            if low <= 0:
                dp_cur[j] = prefix[j]
            else:
                dp_cur[j] = (prefix[j] - prefix[low - 1]) % MOD
        dp_prev = dp_cur
    return dp_prev[m] % MOD

def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0
    # Longest increasing subsequence ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1
    # Longest decreasing subsequence starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1
    # Find maximum bitonic subsequence length
    max_len = 0
    for i in range(n):
        cur = lis[i] + lds[i] - 1
        if cur > max_len:
            max_len = cur
    return n - max_len
